import{_ as c,C as a,o as u,c as p,j as t,a as o,E as s,w as d,a6 as i}from"./chunks/framework.5dd0l9Wo.js";const _=JSON.parse('{"title":"Race Conditions · Case File (Mental Model)","description":"Time-of-check to time-of-use windows, limit overruns, multi-endpoint races, and single-packet attacks explained like a detective investigation.","frontmatter":{"title":"Race Conditions · Case File (Mental Model)","description":"Time-of-check to time-of-use windows, limit overruns, multi-endpoint races, and single-packet attacks explained like a detective investigation."},"headers":[],"relativePath":"race-conditions/index.md","filePath":"race-conditions/index.md"}'),h={name:"race-conditions/index.md"},m={class:"wd-callout"},g={class:"details custom-block"};function w(v,e,f,b,k,y){const r=a("Term"),n=a("LabGroup"),l=a("TopicComplete");return u(),p("div",null,[e[15]||(e[15]=t("h1",{id:"race-conditions-·-the-core-investigation",tabindex:"-1"},[o("Race Conditions · The Core Investigation "),t("a",{class:"header-anchor",href:"#race-conditions-·-the-core-investigation","aria-label":'Permalink to "Race Conditions · The Core Investigation"'},"​")],-1)),e[16]||(e[16]=t("p",{class:"wd-section-lede"},"It is easy to picture web requests as an orderly single-file line where Request A finishes completely before Request B begins. In reality, modern web servers process dozens of requests simultaneously across parallel worker threads. When an application checks a security rule in one step and saves the result in a second step, multiple requests arriving in the exact same millisecond can both pass the check before either one has updated the database.",-1)),t("div",m,[t("p",null,[e[1]||(e[1]=t("strong",null,"💡 Everyday Analogy: The Shared Fridge & The Last Slice of Cake.",-1)),e[2]||(e[2]=o(" Imagine you and your roommate both look into the fridge at 3:00:00 PM and see one remaining slice of chocolate cake. You both decide to eat it. You walk to the counter to grab a plate; your roommate walks over with a fork. Because both of you ",-1)),e[3]||(e[3]=t("em",null,"checked",-1)),e[4]||(e[4]=o(" before either of you ",-1)),e[5]||(e[5]=t("em",null,"took",-1)),e[6]||(e[6]=o(" the cake, you both proceed under the belief that the cake belongs to you. In computing, this split-second gap is called ",-1)),s(r,{id:"toctou-race"},{default:d(()=>[...e[0]||(e[0]=[o("Time-of-Check to Time-of-Use (TOCTOU)",-1)])]),_:1}),e[7]||(e[7]=o(".",-1))])]),e[17]||(e[17]=i('<h2 id="case-file-1-the-one-time-coupon-overrun" tabindex="-1">Case File #1: The One-Time Coupon Overrun <a class="header-anchor" href="#case-file-1-the-one-time-coupon-overrun" aria-label="Permalink to &quot;Case File #1: The One-Time Coupon Overrun&quot;">​</a></h2><p>Let&#39;s trace what happens when an online shopper applies a promotional discount code to their cart.</p><div class="wd-case"><div class="wd-step wd-step--see"><span class="wd-step__tag">🔎 Step 1 · What You Notice in the Browser</span><p>You have a single-use promo code <code>SAVE20</code>. When you enter it and press &quot;Apply&quot;, the store deducts 20% from your order. If you try submitting the code a second time, the store cleanly displays: <em>&quot;Error: Promo code already redeemed.&quot;</em></p></div><div class="wd-step wd-step--server"><span class="wd-step__tag">⚙️ Step 2 · What the Server Does Behind the Scenes</span><p>The backend application performs a multi-step sequence: first, it checks the database to confirm the coupon has not been used yet; then it calculates the new cart price; finally, it marks the coupon as used.</p><div class="wd-codesplit"><div class="wd-codesplit__legend"><span><span class="wd-code-dev">Blue</span> = Step 1: Database Check</span><span><span class="wd-code-input">Gold</span> = Step 2: Database Update</span></div><span class="wd-code-dev">SELECT is_used FROM coupons WHERE code = &#39;SAVE20&#39;</span><br><span class="wd-code-input">UPDATE coupons SET is_used = true WHERE code = &#39;SAVE20&#39;</span></div></div><div class="wd-step wd-step--break"><span class="wd-step__tag">💥 Step 3 · Where the Logic Breaks</span><p>The check and the update are two independent database statements separated in time. If an investigator sends 20 identical redemption requests at the exact same millisecond, all 20 threads execute the check step <em>before</em> any thread completes the update step. Because all 20 read <code>is_used == false</code>, all 20 threads apply the 20% discount, reducing a multi-thousand-dollar shopping cart to pennies!</p></div><div class="wd-step wd-step--fix"><span class="wd-step__tag">🛡️ Step 4 · How Developers Lock It Down</span><p>Developers move the check and the update into a single atomic database operation (e.g., <code>UPDATE coupons SET is_used = true WHERE code = &#39;SAVE20&#39; AND is_used = false</code>) and verify that exactly one row was affected, or use strict database row locks (<code>SELECT ... FOR UPDATE</code>).</p></div></div><h3 id="visual-comparison-orderly-queue-vs-concurrent-collision" tabindex="-1">Visual Comparison: Orderly Queue vs. Concurrent Collision <a class="header-anchor" href="#visual-comparison-orderly-queue-vs-concurrent-collision" aria-label="Permalink to &quot;Visual Comparison: Orderly Queue vs. Concurrent Collision&quot;">​</a></h3><div class="wd-compare"><div class="wd-compare__card wd-compare__card--expect"><span class="wd-compare__title">💭 What the Developer Expected</span><p>The developer assumed requests arrive one after another: Request 1 checks the coupon, marks it used, and finishes. Request 2 arrives later, sees <code>is_used == true</code>, and is rejected.</p></div><div class="wd-compare__card wd-compare__card--actual"><span class="wd-compare__title">💥 What Actually Happened</span><p>Requests 1 through 10 arrive in parallel within a 5-millisecond window. All 10 threads read <code>is_used == false</code> before any thread commits the update, multiplying the discount 10 times.</p></div></div><h3 id="color-coded-breakdown-interleaved-worker-threads" tabindex="-1">Color-Coded Breakdown: Interleaved Worker Threads <a class="header-anchor" href="#color-coded-breakdown-interleaved-worker-threads" aria-label="Permalink to &quot;Color-Coded Breakdown: Interleaved Worker Threads&quot;">​</a></h3><p>Look at how two concurrent requests interleave their execution steps inside the server:</p><div class="wd-codesplit"><div class="wd-codesplit__legend"><span><span class="wd-code-dev">Blue</span> = Thread A Execution</span><span><span class="wd-code-input">Gold</span> = Thread B Execution</span><span><span class="wd-code-dead">Gray</span> = Resulting Database State</span></div><span class="wd-code-dev">[Thread A] Checks balance ($100 &gt;= $100? Yes)</span><br><span class="wd-code-input">[Thread B] Checks balance ($100 &gt;= $100? Yes)</span><br><span class="wd-code-dev">[Thread A] Deducts $100 and ships item</span><br><span class="wd-code-input">[Thread B] Deducts $100 and ships item</span><br><span class="wd-code-dead">Database balance is now -$100; two items shipped for the price of one!</span></div><hr><h2 id="the-4-stage-lifecycle-of-concurrency-collisions" tabindex="-1">The 4-Stage Lifecycle of Concurrency Collisions <a class="header-anchor" href="#the-4-stage-lifecycle-of-concurrency-collisions" aria-label="Permalink to &quot;The 4-Stage Lifecycle of Concurrency Collisions&quot;">​</a></h2><p>Every race condition exploitation flow relies on shrinking network jitter and landing requests in the execution gap:</p><div class="wd-flow"><div class="wd-flow__node"><strong>1. Request Synchronization</strong> Send requests using HTTP/2 multiplexing or single-packet TCP to eliminate network jitter. </div><span class="wd-flow__arrow">→</span><div class="wd-flow__node wd-flow__node--danger"><strong>2. Parallel Ingestion</strong> Server web workers spawn simultaneous threads to process the incoming requests. </div><span class="wd-flow__arrow">→</span><div class="wd-flow__node wd-flow__node--danger"><strong>3. Simultaneous Inspection</strong> Multiple threads read the current database record before any thread can modify it. </div><span class="wd-flow__arrow">→</span><div class="wd-flow__node wd-flow__node--safe"><strong>4. Conflicted Commitment</strong> All threads commit their actions, resulting in limit overruns, duplicate credits, or bypassed state gates. </div></div><hr><h2 id="the-detective-s-investigation-playbook" tabindex="-1">The Detective&#39;s Investigation Playbook <a class="header-anchor" href="#the-detective-s-investigation-playbook" aria-label="Permalink to &quot;The Detective&#39;s Investigation Playbook&quot;">​</a></h2><h3 id="_1-limit-overruns-rate-limit-bypasses" tabindex="-1">1. Limit Overruns &amp; Rate-Limit Bypasses <a class="header-anchor" href="#_1-limit-overruns-rate-limit-bypasses" aria-label="Permalink to &quot;1. Limit Overruns &amp; Rate-Limit Bypasses&quot;">​</a></h3><p>The most common race condition is the <strong>limit overrun</strong>: multiplying an action that should only be permitted a fixed number of times.</p><ul><li><strong>Discount &amp; Gift Card Duplication:</strong> Redeeming a one-time promo code or gift card balance multiple times.</li><li><strong>Vote &amp; Rating Inflation:</strong> Submitting multiple rating points when each user is limited to one vote.</li><li><strong>Login Rate-Limit Evasion:</strong> Sending 50 password guesses concurrently. If the counter that tracks failed attempts reads and increments asynchronously, all 50 attempts can land before the lock threshold triggers.</li></ul>',17)),s(n,{ids:"race-conditions-lab-race-conditions-limit-overrun, race-conditions-lab-race-conditions-bypassing-rate-limits"}),t("details",g,[e[11]||(e[11]=t("summary",null,"🔬 Under the Hood: The Single-Packet Attack",-1)),e[12]||(e[12]=t("p",null,"When testing for race conditions over standard HTTP/1.1 connections, network jitter (slight delays across routers and cables) can spread request arrival times by 10–50 milliseconds—wide enough for the server to finish the first request before the second arrives.",-1)),e[13]||(e[13]=t("p",null,[o("The "),t("strong",null,"single-packet attack"),o(" eliminates network jitter:")],-1)),e[14]||(e[14]=t("ol",null,[t("li",null,"Open multiple TCP connections or HTTP/2 streams to the server."),t("li",null,"Send all HTTP request headers and almost all of the request body, but hold back the final byte."),t("li",null,"Release the final byte of all requests simultaneously inside a single TCP packet.")],-1)),t("p",null,[e[9]||(e[9]=o("Because all requests complete their transmission in the exact same microsecond, the server's network card and web worker threads receive them at identical times, maximizing the chance of hitting the ",-1)),s(r,{id:"toctou-race"},{default:d(()=>[...e[8]||(e[8]=[o("TOCTOU window",-1)])]),_:1}),e[10]||(e[10]=o(".",-1))])]),e[18]||(e[18]=i('<hr><h3 id="_2-multi-endpoint-single-endpoint-sub-state-races" tabindex="-1">2. Multi-Endpoint &amp; Single-Endpoint Sub-State Races <a class="header-anchor" href="#_2-multi-endpoint-single-endpoint-sub-state-races" aria-label="Permalink to &quot;2. Multi-Endpoint &amp; Single-Endpoint Sub-State Races&quot;">​</a></h3><p>Not all race conditions send the identical request to the identical endpoint:</p><ul><li><strong>Multi-Endpoint Races:</strong> Target shared application state accessed by two different endpoints. For example, triggering a checkout request (<code>POST /cart/checkout</code>) while simultaneously modifying cart contents (<code>POST /cart/add-item</code>) can result in paying the low price while receiving the high-value item.</li><li><strong>Single-Endpoint Races:</strong> Send the same endpoint different values. For example, racing an email-change request against a password-reset request can cause the password reset token to be generated and delivered to an intermediate email address during state transition.</li></ul>',4)),s(n,{ids:"race-conditions-lab-race-conditions-multi-endpoint, race-conditions-lab-race-conditions-single-endpoint"}),e[19]||(e[19]=t("hr",null,null,-1)),e[20]||(e[20]=t("h3",{id:"_3-time-sensitive-tokens-partial-construction-windows",tabindex:"-1"},[o("3. Time-Sensitive Tokens & Partial Construction Windows "),t("a",{class:"header-anchor",href:"#_3-time-sensitive-tokens-partial-construction-windows","aria-label":'Permalink to "3. Time-Sensitive Tokens & Partial Construction Windows"'},"​")],-1)),e[21]||(e[21]=t("ul",null,[t("li",null,[t("strong",null,"Time-Sensitive Token Collisions:"),o(" Some password-reset or session token generators seed their pseudorandom generator using the server's current millisecond timestamp ("),t("code",null,"System.currentTimeMillis()"),o("). Sending two reset requests at the same instant can generate identical reset tokens for two different accounts.")]),t("li",null,[t("strong",null,"Partial Construction Windows:"),o(" When an application creates a new account or resource, it often performs setup in stages (e.g., insert base user record, then initialize security flags, then set permissions). Requesting the account or logging in during the microsecond window between record insertion and permission initialization can catch the object in an unvalidated, half-built state.")])],-1)),s(n,{ids:"race-conditions-lab-race-conditions-exploiting-time-sensitive-vulnerabilities, race-conditions-lab-race-conditions-partial-construction"}),e[22]||(e[22]=i('<details class="details custom-block"><summary>⚙️ Engine Variations: Where Real Atomicity Comes From</summary><p>Application-level locks (like in-memory mutexes) fail completely when web applications run on multiple server instances or containers. True atomicity must come from the data layer:</p><table tabindex="0"><thead><tr><th>Datastore</th><th>Non-Atomic Pattern (Vulnerable)</th><th>Atomic Primitive (Safe)</th></tr></thead><tbody><tr><td><strong>PostgreSQL / MySQL</strong></td><td><code>SELECT balance;</code> then <code>UPDATE balance;</code></td><td><code>UPDATE accounts SET balance = balance - 100 WHERE id = 1 AND balance &gt;= 100;</code> or <code>SELECT ... FOR UPDATE</code></td></tr><tr><td><strong>Redis</strong></td><td><code>GET key;</code> then <code>SET key;</code></td><td><code>INCR</code>, <code>SETNX</code>, or atomic Lua scripts (<code>EVAL</code>)</td></tr><tr><td><strong>MongoDB</strong></td><td>Read document then call <code>save()</code></td><td><code>findOneAndUpdate({ _id: id, count: { $gt: 0 } }, { $inc: { count: -1 } })</code></td></tr><tr><td><strong>File Counters</strong></td><td>Read file, increment, write file</td><td><code>flock()</code> advisory locking (though unreliable across networked NFS)</td></tr></tbody></table></details><hr><h2 id="the-detective-s-concurrency-testing-routine" tabindex="-1">The Detective&#39;s Concurrency Testing Routine <a class="header-anchor" href="#the-detective-s-concurrency-testing-routine" aria-label="Permalink to &quot;The Detective&#39;s Concurrency Testing Routine&quot;">​</a></h2><p>When hunting for race conditions:</p><ol><li><strong>Identify Check-Then-Act Logic:</strong> Look for any high-value operation guarded by a condition: coupons, account balances, transfer limits, one-time invitation tokens, and login lockouts.</li><li><strong>Benchmark Normal Flow:</strong> Measure the normal response time and database state changes of a single request.</li><li><strong>Synchronize Requests:</strong> Group 10 to 30 requests in Burp Repeater or Turbo Intruder and configure HTTP/2 single-packet synchronization.</li><li><strong>Inspect State Anomalies:</strong> Check whether balances went negative, duplicate orders were placed, or discount codes were applied multiple times.</li><li><strong>Vary Endpoint Pairs:</strong> Test racing one state-changing request (e.g., checkout) against another state-altering action (e.g., modifying delivery address or adding cart items).</li></ol><hr><h2 id="how-developers-lock-it-down-permanently" tabindex="-1">How Developers Lock It Down Permanently <a class="header-anchor" href="#how-developers-lock-it-down-permanently" aria-label="Permalink to &quot;How Developers Lock It Down Permanently&quot;">​</a></h2><div class="wd-callout wd-callout--warn"><p><strong>🛡️ The Golden Rules of Concurrency Defense:</strong></p><ul><li><strong>Use Atomic Conditional Updates:</strong> Execute state updates with embedded conditions (<code>UPDATE coupons SET used = true WHERE id = ? AND used = false</code>) and check that the affected row count is 1.</li><li><strong>Enforce Database Constraints:</strong> Use database-level unique constraints (e.g., unique index on <code>(user_id, promo_id)</code>) so the database itself rejects duplicate inserts, regardless of thread timing.</li><li><strong>Apply Transaction Isolation &amp; Row Locks:</strong> When multi-step operations are required, wrap them in a transaction with <code>SERIALIZABLE</code> isolation or use pessimistic locking (<code>SELECT ... FOR UPDATE</code>).</li><li><strong>Use Centralized Atomic Counters:</strong> For rate limits, use distributed atomic stores like Redis <code>INCR</code> with immediate expiration rather than asynchronous database counters.</li><li><strong>Audit Object Lifecycle States:</strong> Ensure new records are created in a disabled or pending state and only activated after all security initializations complete.</li></ul></div>',8)),s(l,{"topic-id":"race-conditions",label:"Mark race conditions complete"})])}const C=c(h,[["render",w]]);export{_ as __pageData,C as default};
